    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationByName"("Missing"));
    try std.testing.expectEqualStrings("Color", generated.@"cpz.declarationById"(0xc010).?.name);
    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationById"(0xdead));
    try std.testing.expectEqualStrings("Person", generated.@"cpz.declarationByKind"(.struct_decl).?.name);
    try std.testing.expectEqualStrings("Person", generated.@"cpz.declarationByAnnotations"("$schemaNote(\"person\")").?.name);
    try std.testing.expectEqualStrings("Choice", generated.@"cpz.declarationByAnnotations"("").?.name);
    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationByAnnotations"("missing"));
    try std.testing.expectEqualStrings("Color", generated.@"cpz.declarationByKind"(.enum_decl).?.name);
    try std.testing.expectEqualStrings("Service", generated.@"cpz.declarationByKind"(.interface_decl).?.name);
    try std.testing.expectEqualStrings("enumNote", generated.@"cpz.declarationByKind"(.annotation_decl).?.name);
    try std.testing.expectEqualStrings("GenericBox", generated.@"cpz.declarationByParameter"("T").?.name);
    try std.testing.expectEqualStrings("ExtendedService", generated.@"cpz.declarationByParameter"("Req").?.name);
    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationByParameter"("Missing"));
    try std.testing.expectEqualStrings("Person", generated.@"cpz.declarationByParameterCount"(0).?.name);
    try std.testing.expectEqualStrings("GenericBox", generated.@"cpz.declarationByParameterCount"(1).?.name);
    try std.testing.expectEqualStrings("ExtendedService", generated.@"cpz.declarationByParameterCount"(2).?.name);
    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationByParameterCount"(99));
    try std.testing.expectEqualStrings("Color", generated.@"cpz.declarationByIndex"(12).?.name);
    try std.testing.expectEqual(@as(?cpz.schema.DeclarationMetadata, null), generated.@"cpz.declarationByIndex"(999));
