    try std.testing.expect(generated.@"cpz.declarations"[10].matchesParameter("T"));
    try std.testing.expect(!generated.@"cpz.declarations"[10].matchesParameter("Missing"));
    try std.testing.expectEqualStrings("T", generated.@"cpz.declarations"[10].parameterByName("T").?);
    try std.testing.expectEqualStrings("T", generated.@"cpz.declarations"[10].parameterByIndex(0).?);
    try std.testing.expectEqual(@as(?[]const u8, null), generated.@"cpz.declarations"[10].parameterByName("Missing"));
    try std.testing.expectEqual(@as(?[]const u8, null), generated.@"cpz.declarations"[10].parameterByIndex(99));
    try std.testing.expectEqual(@as(usize, 1), generated.@"cpz.declaration.GenericBox.parameterCount");
    try std.testing.expectEqualSlices([]const u8, &[_][]const u8{"T"}, generated.@"cpz.declaration.GenericBox.parameters");
    try std.testing.expectEqualStrings("T", generated.@"cpz.declaration.GenericBox.parameters.parameterByName"("T").?);
    try std.testing.expectEqualStrings("T", generated.@"cpz.declaration.GenericBox.parameters.parameterByIndex"(0).?);
    try std.testing.expectEqual(@as(?[]const u8, null), generated.@"cpz.declaration.GenericBox.parameters.parameterByName"("Missing"));
    try std.testing.expectEqualStrings("Color", generated.@"cpz.declarations"[12].name);
    try std.testing.expectEqual(@as(usize, 0), generated.@"cpz.declarations"[12].parameter_count);
    try std.testing.expectEqual(@as(usize, 0), generated.@"cpz.declaration.Color.parameterCount");
    try std.testing.expectEqual(.enum_decl, generated.@"cpz.declarations"[12].kind);
    try std.testing.expectEqual(@as(?u64, 0xc010), generated.@"cpz.declarations"[12].id);
    try std.testing.expectEqual(@as(?u64, 0xc010), generated.@"cpz.declaration.Color.id");
    try std.testing.expectEqualStrings("Color", generated.@"cpz.declaration.Color.metadata".name);
    try std.testing.expectEqual(.enum_decl, generated.@"cpz.declaration.Color.metadata".kind);
    try std.testing.expectEqual(.enum_decl, generated.@"cpz.declaration.Color.kind");
    try std.testing.expectEqualStrings("ExtendedService", generated.@"cpz.declarations"[16].name);
    try std.testing.expectEqual(.interface_decl, generated.@"cpz.declarations"[16].kind);
    try std.testing.expectEqual(@as(usize, 2), generated.@"cpz.declarations"[16].parameter_count);
    try std.testing.expectEqualSlices([]const u8, &[_][]const u8{ "Req", "Resp" }, generated.@"cpz.declarations"[16].parameters);
    try std.testing.expectEqual(@as(usize, 2), generated.@"cpz.declaration.ExtendedService.parameterCount");
    try std.testing.expectEqualStrings("ExtendedService", generated.@"cpz.declaration.ExtendedService.metadata".name);
    try std.testing.expectEqual(@as(usize, 2), generated.@"cpz.declaration.ExtendedService.metadata".parameter_count);
    try std.testing.expectEqualStrings("Req", generated.@"cpz.declaration.ExtendedService.metadata".parameterByName("Req").?);
    try std.testing.expectEqualStrings("Resp", generated.@"cpz.declaration.ExtendedService.metadata".parameterByIndex(1).?);
    try std.testing.expectEqualSlices([]const u8, &[_][]const u8{ "Req", "Resp" }, generated.@"cpz.declaration.ExtendedService.parameters");
    try std.testing.expectEqualStrings("Req", generated.@"cpz.declaration.ExtendedService.parameters.parameterByName"("Req").?);
    try std.testing.expectEqualStrings("Resp", generated.@"cpz.declaration.ExtendedService.parameters.parameterByIndex"(1).?);
    try std.testing.expectEqual(@as(?[]const u8, null), generated.@"cpz.declaration.ExtendedService.parameters.parameterByIndex"(99));
    try std.testing.expectEqualStrings("schemaNote", generated.@"cpz.declarations"[18].name);
    try std.testing.expectEqual(.annotation_decl, generated.@"cpz.declarations"[18].kind);
    try std.testing.expectEqual(@as(?u64, 0xa110ca110c), generated.@"cpz.declarations"[18].id);
    try std.testing.expectEqual(@as(u64, 0xc010), generated.Color.@"cpz.type_id");
    try std.testing.expectEqual(@as(u64, 0xd00d), generated.DynamicBox.@"cpz.type_id");
    try std.testing.expectEqual(@as(u64, 0xe57e0001), generated.ExtendedService.@"cpz.type_id");
    try std.testing.expectEqual(generated.Person.size, generated.Person.@"cpz.structSize");
    try std.testing.expectEqual(generated.Person.size.data_words, generated.Person.@"cpz.dataWordCount");
    try std.testing.expectEqual(generated.Person.size.pointer_count, generated.Person.@"cpz.pointerCount");
    try std.testing.expectEqual(generated.Choice.size, generated.Choice.@"cpz.structSize");
    try std.testing.expectEqual(@as(usize, 8), generated.@"cpz.aliasCount");
    try std.testing.expectEqual(@as(usize, 8), generated.@"cpz.aliases".len);
    try std.testing.expectEqualStrings("Id", generated.@"cpz.aliases"[0].name);
    try std.testing.expectEqual(@as(usize, 0), generated.@"cpz.aliases"[0].index);
    try std.testing.expectEqualStrings("Names", generated.@"cpz.aliasByName"("Names").?.name);
    try std.testing.expectEqual(@as(usize, 2), generated.@"cpz.aliasByName"("Names").?.index);
    try std.testing.expectEqual(@as(?cpz.schema.AliasMetadata, null), generated.@"cpz.aliasByName"("Missing"));
    try std.testing.expectEqualStrings("Id", generated.@"cpz.aliasByTarget"("UInt32").?.name);
    try std.testing.expectEqualStrings("Names", generated.@"cpz.aliasByResolvedTarget"("List(Text)").?.name);
    try std.testing.expectEqual(@as(?cpz.schema.AliasMetadata, null), generated.@"cpz.aliasByTarget"("Missing"));
    try std.testing.expectEqual(@as(?cpz.schema.AliasMetadata, null), generated.@"cpz.aliasByResolvedTarget"("Missing"));
    try std.testing.expectEqualStrings("Names", generated.@"cpz.aliasByIndex"(2).?.name);
    try std.testing.expectEqual(@as(?cpz.schema.AliasMetadata, null), generated.@"cpz.aliasByIndex"(99));
