    const children = try target_person_builder.init_children(10);
    try children.set(0, source_person);
    try children.copyFrom(1, source_children, 0);
    try children.copyFromBuilder(2, source_children_builder, 0);
    try children.copyRangeFrom(3, source_children, 0, 1);
    try children.copyRangeFromBuilder(4, source_children_builder, 0, 1);

    try children.copyCanonicalFrom(6, source_children, 0);
    try children.copyCanonicalFromBuilder(7, source_children_builder, 0);
    try children.copyCanonicalRangeFrom(8, source_children, 0, 1);
    try children.copyCanonicalRangeFromBuilder(9, source_children_builder, 0, 1);

    var direct_source_builder = try cpz.MessageBuilder.init(std.testing.allocator, .{ .first_segment_words = 8 });
    defer direct_source_builder.deinit();
    const direct_builder_child = try generated.Person.initRootTyped(&direct_source_builder);
    try direct_builder_child.set_id(777);
    try direct_builder_child.set_name("DirectBuilder");
    try children.setFromBuilder(5, direct_builder_child);

    var target_reader = cpz.MessageReader.init(try target_builder.segmentsConst(), .{});
    const target_person = generated.Person.fromReader(try target_reader.getRoot());
    const read_children = try target_person.children();
    const child = try read_children.get(0);
    try std.testing.expectEqual(@as(u32, 321), child.id());
    try std.testing.expectEqualSlices(u8, "ListCopy", try child.name());
    const copied_child = try read_children.get(1);
    try std.testing.expectEqual(@as(u32, 654), copied_child.id());
    try std.testing.expectEqualSlices(u8, "ElementCopy", try copied_child.name());
    const copied_builder_child = try read_children.get(2);
    try std.testing.expectEqual(@as(u32, 654), copied_builder_child.id());
    try std.testing.expectEqualSlices(u8, "ElementCopy", try copied_builder_child.name());
    const copied_range_child = try read_children.get(3);
    try std.testing.expectEqual(@as(u32, 654), copied_range_child.id());
    try std.testing.expectEqualSlices(u8, "ElementCopy", try copied_range_child.name());
    const copied_builder_range_child = try read_children.get(4);
    try std.testing.expectEqual(@as(u32, 654), copied_builder_range_child.id());
    try std.testing.expectEqualSlices(u8, "ElementCopy", try copied_builder_range_child.name());
    const direct_builder_copied_child = try read_children.get(5);
    try std.testing.expectEqual(@as(u32, 777), direct_builder_copied_child.id());
    try std.testing.expectEqualSlices(u8, "DirectBuilder", try direct_builder_copied_child.name());
    try std.testing.expect(read_children.structElementSize().pointer_count == generated.Person.size.pointer_count);
    const canonical_child = try read_children.get(6);
    try std.testing.expectEqual(@as(u32, 654), canonical_child.id());
    try std.testing.expectEqualSlices(u8, "ElementCopy", try canonical_child.name());
    const canonical_builder_child = try read_children.get(7);
    try std.testing.expectEqual(@as(u32, 654), canonical_builder_child.id());
    const canonical_range_child = try read_children.get(8);
    try std.testing.expectEqual(@as(u32, 654), canonical_range_child.id());
    const canonical_builder_range_child = try read_children.get(9);
    try std.testing.expectEqual(@as(u32, 654), canonical_builder_range_child.id());
}

