test "generated generic type applications lower to base accessors" {
    try std.testing.expectEqual(@as(usize, 1), generated.GenericBox.@"cpz.parameterCount");
    try std.testing.expectEqualSlices([]const u8, &[_][]const u8{"T"}, generated.GenericBox.@"cpz.parameters");
    try std.testing.expectEqual(@as(usize, 0), generated.GenericBox.@"cpz.parameter.T.index");
    try std.testing.expectEqualStrings("T", generated.GenericBox.@"cpz.parameter.T.name");
    try std.testing.expectEqualStrings("T", generated.GenericBox.@"cpz.parameters.parameterByName"("T").?);
    try std.testing.expectEqualStrings("T", generated.GenericBox.@"cpz.parameters.parameterByIndex"(0).?);
    try std.testing.expectEqual(@as(?[]const u8, null), generated.GenericBox.@"cpz.parameters.parameterByName"("Missing"));

    var source_builder = try cpz.MessageBuilder.init(std.testing.allocator, .{ .first_segment_words = 8 });
    defer source_builder.deinit();
    const source_person_builder = try generated.Person.initRootTyped(&source_builder);
    try source_person_builder.set_id(8181);
    try source_person_builder.set_name("generic person");
    var source_reader = cpz.MessageReader.init(try source_builder.segmentsConst(), .{});
    const source_ptr = try source_reader.getRootPointer();

    var builder = try cpz.MessageBuilder.init(std.testing.allocator, .{ .first_segment_words = 32 });
    defer builder.deinit();

    const box_builder = try generated.GenericUseBox.initRootTyped(&builder);
    const direct = try box_builder.init_direct();
    try direct.set_value_from(source_ptr);
    try direct.set_value_fromBuilder(try source_builder.getRootPointer());
    const alias = try box_builder.init_alias();
    try alias.set_value_canonicalFrom(source_ptr);
    try alias.set_value_canonicalFromBuilder(try source_builder.getRootPointer());
    var alias_copy_orphan = try alias.new_value_copyOrphan(source_ptr);
    try alias.adopt_value(&alias_copy_orphan);
    var alias_copy_orphan_builder = try alias.new_value_copyOrphanFromBuilder(try source_builder.getRootPointer());
    try alias.adopt_value(&alias_copy_orphan_builder);
    var alias_copy_orphan_canonical = try alias.new_value_copyOrphanCanonical(source_ptr);
    try alias.adopt_value(&alias_copy_orphan_canonical);
    var alias_copy_orphan_canonical_builder = try alias.new_value_copyOrphanCanonicalFromBuilder(try source_builder.getRootPointer());
    try alias.adopt_value(&alias_copy_orphan_canonical_builder);
    const alias_items = try alias.init_items(2);
    try alias_items.set(0, source_ptr);
    try alias_items.setFromBuilder(1, try source_builder.getRootPointer());
    try alias_items.setCanonical(0, source_ptr);
    try alias_items.setCanonicalFromBuilder(1, try source_builder.getRootPointer());
    var alias_item_orphan = try alias_items.newCopyOrphan(source_ptr);
    try alias_items.adopt(0, &alias_item_orphan);
    var alias_item_builder_orphan = try alias_items.newCopyOrphanFromBuilder(try source_builder.getRootPointer());
    try alias_items.adopt(1, &alias_item_builder_orphan);
    var alias_item_canonical_orphan = try alias_items.newCopyOrphanCanonical(source_ptr);
    try alias_items.adopt(0, &alias_item_canonical_orphan);
    var alias_item_canonical_builder_orphan = try alias_items.newCopyOrphanCanonicalFromBuilder(try source_builder.getRootPointer());
    try alias_items.adopt(1, &alias_item_canonical_builder_orphan);
    var alias_items_builder_reader = cpz.MessageReader.init(try builder.segmentsConst(), .{});
    var alias_items_orphan = try generated.GenericBox.GenericBox_items_Orphan.newOrphanCopyCanonical(&builder, alias_items.asReader(&alias_items_builder_reader));
    try alias.adopt_items_typed(&alias_items_orphan);
